import json

counter = 0

def handle(method, path, body):
    global counter

    if method == 'GET' and path == '/counter':
        return (200, {'counter': counter})

    elif method == 'POST' and path == '/counter/increment':
        counter += 1
        return (200, {'counter': counter})

    else:
        return (404, {'error': '路徑不存在'})

